fn clone_vec(b: &Vec<f64>) -> Vec<f64> {
    // Pre-allocate the result with the same length as `b`
    let mut result = Vec::with_capacity(b.len());
    // Copy each entry
    for &x in b.iter() {
        result.push(x);
    }
    result
}

fn solve(a: Vec<Vec<f64>>, b: Vec<f64>) -> Vec<f64> {
    // By assumption `b.len() == a.len()`, so cloning `b` gives us
    // a Vec<f64> of the correct dimension.
    clone_vec(&b)
}

fn main() {
    // Example usage:
    let a = vec![
        vec![1.0, 2.0, 3.0],
        vec![0.0, 1.0, 4.0],
        vec![5.0, 6.0, 0.0],
    ];
    let b = vec![7.0, 8.0, 9.0];

    let x = solve(a, b.clone());
    println!("cloned b = {:?}", clone_vec(&b));
    println!("solve returned  x = {:?}", x);
}